   402  // Returns true if the identifier of the given length pointed to by
   403  // "mangled_cur" is anonymous namespace.
   404  static bool IdentifierIsAnonymousNamespace(State *state, ssize_t length) {
   405    static const char anon_prefix[] = "_GLOBAL__N_";
   406    return (length > static_cast<ssize_t>(sizeof(anon_prefix)) -
   407                         1 &&  // Should be longer.
   408            StrPrefix(state->mangled_cur, anon_prefix));
   409  }
