  1212    *state = copy;
  1213
  1214    if (ParseOneCharToken(state, 'L') && ParseType(state) &&
  1215        ParseFloatNumber(state) &&
  1216        ParseOneCharToken(state, 'E')) {
  1217      return true;
  1218    }
  1219    *state = copy;
  1220
  1221    if (ParseOneCharToken(state, 'L') && ParseMangledName(state) &&
