   184  // Returns true if "str" has "prefix" as a prefix.
   185  static bool StrPrefix(const char *str, const char *prefix) {
   186    size_t i = 0;
   187    while (str[i] != '\0' && prefix[i] != '\0' &&
   188           str[i] == prefix[i]) {
   189      ++i;
   190    }
   191    return prefix[i] == '\0';  // Consumed everything in "prefix".
   192  }
